// Demo: Stereo Vision Processor - Signature build-tool concept
(function(){'use strict';
var DATA={"label": "Stereo Vision Processor - Signature build-tool concept", "rows": [["OpenCV", "41"], ["  OpenCV ", "46"], ["ResNet", "69"], ["YOLO", "46"], ["  YOLO ", "73"], ["Vision Transformers", "67"], ["Tesseract", "12"], ["  Tesseract ", "13"], ["", ""], ["OpenCV", "42"]]};

var seen={},kept=[],droppedEmpty=0,droppedDup=0;
console.log('Cleaning '+DATA.rows.length+' rows ('+DATA.label+'):');
